 prefix='' if home else '/'
 return f'''<header class="site-header wrap"><a class="brand" href="/" aria-label="Tischlerei Mehlig Startseite"><img src="/assets/logo.svg" alt="Tischlerei Mehlig" width="45" height="58"><span>Mehlig</span></a><nav id="navigation" aria-label="Hauptnavigation"><a href="{prefix}#projekte">Projekte</a><a href="{prefix}#leistungen">Leistungen</a><a href="{prefix}#unternehmen">Unternehmen</a><a href="{prefix}#kontakt">Kontakt</a></nav><a class="careers-link" href="/karriere">Jetzt bewerben</a><button class="mobile-menu" aria-controls="navigation" aria-expanded="false">Menü</button></header>'''
