def dialogs():return f'''<dialog id="gallery-dialog" aria-labelledby="gallery-title"><div class="viewer-shell"><button class="dialog-close" aria-label="Bild schließen">{close}</button><div class="viewer-stage"><p class="viewer-brand">Mehlig <span>/ Projekte</span></p><div class="viewer-toolbar"><span id="viewer-image-count"></span><div><button id="viewer-zoom" aria-pressed="false">Vergrößern</button><button id="viewer-fullscreen">Vollbild</button></div></div><div class="viewer-frame" id="viewer-frame"><img id="gallery-large" alt="" decoding="async"></div><div class="gallery-controls"><button id="gallery-previous" aria-label="Vorheriges Bild">Zurück</button><p id="gallery-position" aria-live="polite"></p><button id="gallery-next" aria-label="Nächstes Bild">Weiter</button></div><div class="viewer-filmstrip" id="viewer-filmstrip" aria-label="Projektaufnahmen"></div></div><aside class="viewer-info"><p class="viewer-category" id="viewer-category"></p><h2 id="gallery-title"></h2><dl id="viewer-details"></dl><a id="viewer-contact" class="text-link" href="mailto:info@mehlig-gmbh.de" data-contact="inquiry">Ähnliches Vorhaben anfragen</a><a id="viewer-project-page" class="quiet-link">Projektseite öffnen</a><p class="viewer-note">Fotografien eines realisierten Projekts. Anforderungen und Materialien für Ihr Vorhaben stimmen wir persönlich ab.</p></aside></div></dialog><dialog id="contact-dialog" aria-labelledby="contact-title"><button class="dialog-close" aria-label="Kontakt schließen">{close}</button><div class="contact-modal"><h2 id="contact-title">Ihr Vorhaben.</h2><p id="contact-intro">Ein kurzer Überblick genügt für den ersten Kontakt.</p><div class="contact-tabs" role="group" aria-label="Kontaktweg"><button data-contact="inquiry" aria-pressed="true">Anfrage</button><button data-contact="callback" aria-pressed="false">Rückruf</button><a href="tel:+49412285943">Anrufen</a></div><form id="inquiry-form"><label>Ihr Name<input name="name" autocomplete="name" maxlength="120" required></label><label>E-Mail<input type="email" name="email" autocomplete="email" maxlength="254" required></label><label>Firma / Planung <span>optional</span><input name="company" autocomplete="organization" maxlength="200"></label><label>Ihr Vorhaben<textarea name="message" rows="4" maxlength="6000" required placeholder="Idee, Nutzung und Ort Ihres Projekts"></textarea></label><button class="button" type="submit">E-Mail vorbereiten</button></form><form id="callback-form" hidden><label>Ihr Name<input name="name" autocomplete="name" maxlength="120" required></label><label>Telefonnummer<input type="tel" name="phone" autocomplete="tel" maxlength="60" required></label><label>Wann passt es Ihnen?<input name="timing" maxlength="200" placeholder="Zum Beispiel vormittags"></label><button class="button" type="submit">Rückrufanfrage vorbereiten</button></form><div id="contact-ready" hidden><h3>Ihre Anfrage ist vorbereitet.</h3><pre id="contact-summary"></pre><a id="prepared-email" class="button">Im E-Mail-Programm öffnen</a><button id="edit-request" class="text-link">Angaben bearbeiten</button></div><p class="modal-note">Die Website versendet keine Nachricht. Sie prüfen und versenden die Anfrage selbst in Ihrem E-Mail-Programm. Fotos und Pläne können Sie dort anhängen. Einen Termin stimmen wir persönlich ab.</p><a class="quiet-link" href="/datenschutz">Datenschutz</a></div></dialog><dialog id="portrait-dialog" aria-labelledby="portrait-name"><button class="dialog-close" aria-label="Porträt schließen">{close}</button><img id="portrait-large" alt=""><div class="portrait-details"><h2 id="portrait-name"></h2><p id="portrait-role"></p><a id="portrait-email"></a></div></dialog>'''
