def tile(p,i):
 a=p['cover'];ratio=max(.7,min(1.55,a['width']/a['height']));ratio=[1.28,.82,1.12,1.35,.9,1.5,.8,1.3][i%8]
 return f'''<article class="photo-item"><a class="gallery-photo" href="/projekte/{p['id']}" data-project="{p['id']}" data-category="{p['category']}" data-ratio="{ratio}" aria-label="{e(p['title'])} ansehen"><img src="{a['path']}" width="{a['width']}" height="{a['height']}" alt="{e(p['title'])} – {e(p['task'])}" loading="{'eager' if i<4 else 'lazy'}" decoding="async"><span class="photo-caption"><span>{e(p['title'])}</span><small>{p['categoryLabel']}</small></span></a></article>'''
