home+=f'''<main id="main"><section class="hero wrap"><div class="hero-copy"><h1>Räume, nach Maß.</h1><p>Innenausbau, Objekteinrichtung und Möbelbau.<br>Für private Räume, Hotels, Gastronomie und Arbeitswelten.</p></div><div class="intro-contact"><a href="tel:+49412285943">04122 85 94 3</a><a href="mailto:info@mehlig-gmbh.de" data-contact="inquiry">Kontakt anfragen</a><a href="mailto:info@mehlig-gmbh.de">info@mehlig-gmbh.de</a></div><figure class="hero-photo"><a href="/projekte/p87" data-project="p87" aria-label="Wiener Café · Hamburg ansehen"><img src="{hero['path']}" width="{hero['width']}" height="{hero['height']}" alt="Wiener Café in Hamburg: grüne Wandvertäfelung, rote Sitzmöbel und Natursteintische" fetchpriority="high"></a><figcaption><span>Wiener Café · Hamburg</span><a href="/projekte/p87" data-project="p87">Projekt ansehen</a></figcaption></figure></section>
<section id="projekte" class="gallery-framework wrap"><div class="archive-heading"><div><h2>Einblicke in unsere Arbeit.</h2><p>Private Räume, Hotels, Gastronomie und Arbeitswelten.</p></div><p>48 Projekte</p></div><div class="archive-console"><div class="gallery-filters" role="group" aria-label="Projekte filtern"><button data-gallery-filter="all" aria-pressed="true">Alle</button><button data-gallery-filter="private" aria-pressed="false">Privat</button><button data-gallery-filter="hotels" aria-pressed="false">Hotels</button><button data-gallery-filter="gastro" aria-pressed="false">Gastronomie</button><button data-gallery-filter="work" aria-pressed="false">Arbeitswelten</button></div><label class="gallery-category-mobile"><span class="sr-only">Galerie filtern</span><select id="gallery-category"><option value="all">Alle Projekte</option><option value="private">Privat</option><option value="hotels">Hotels</option><option value="gastro">Gastronomie</option><option value="work">Arbeitswelten</option></select></label><label class="gallery-search"><span class="sr-only">Projekte durchsuchen</span><input type="search" id="gallery-search" placeholder="Suchen" autocomplete="off"></label><div class="gallery-size"><label for="gallery-density">Bildgröße</label><input type="range" min="2" max="4" value="2" id="gallery-density" aria-valuetext="Große Bilder" aria-label="Bildgröße"></div><div class="gallery-layout" role="group" aria-label="Galerieansicht"><button data-gallery-layout="wall" aria-pressed="true">Bildwand</button><button data-gallery-layout="grid" aria-pressed="false">Raster</button></div></div><div class="reference-gallery" id="photo-results" data-layout="wall">'''
