home+='''</div><p class="group">Ein Unternehmen von <a href="https://gruppenwerk.de/" target="_blank" rel="noopener noreferrer">GRUPPENWERK</a>.</p></section>'''+contactsection()+'''</main><aside class="quick-contact" aria-label="Schnellkontakt"><a href="tel:+49412285943">Anrufen</a><a href="mailto:info@mehlig-gmbh.de" data-contact="inquiry">Kontakt anfragen</a></aside>'''+finish()
(P/'index.html').write_text(home)
for p in projects:
 out=head(p['title'],p['task'])+header()+f'''<main class="project-page wrap" id="main"><a class="quiet-link" href="/#projekte">Zur Projektübersicht</a><div class="project-intro"><h1>{e(p['title'])}</h1><div><p>{p['categoryLabel']}</p><dl><dt>Aufgabe</dt><dd>{e(p['task'])}</dd>'''
